class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def merge_k_lists(lists: list) -> object:
    if not lists:
        return None

    # Helper function to merge two lists
    def merge_two_lists(l1, l2):
        dummy = ListNode()
        current = dummy

        while l1 and l2:
            if l1.val < l2.val:
                current.next = l1
                l1 = l1.next
            else:
                current.next = l2
                l2 = l2.next
            current = current.next

        if l1:
            current.next = l1
        elif l2:
            current.next = l2

        return dummy.next

    # Merge the lists using divide and conquer approach
    while len(lists) > 1:
        merged_list = []
        for i in range(0, len(lists), 2):
            l1 = lists[i]
            l2 = lists[i + 1] if i + 1 < len(lists) else None
            merged_list.append(merge_two_lists(l1, l2))
        lists = merged_list

    return lists[0]

